      "sample": "資料の印刷についてご連絡します。ご希望の紙と色で明日の朝までに完成すると、現時点ではお約束しかねます。機械の色が安定しておらず、確認と調整に時間が必要だからです。ただし、普通の紙で白黒にする場合は、今夜八時までにお渡しできます。ご注文どおりの色をご希望なら、明後日の午後となります。会議で内容を説明することが主な目的であれば、白黒をお選びいただいても問題ないと思います。まだ別の方法がありますから、すぐに注文を取り消すことはないと思います。用途に合う方法を一緒に検討したいので、ご希望をお知らせください。",
