      "jp": "駅前の工房が、修理を学ぶ無料講座を開いた。広告には参加費無料と大きく書かれていたので、私は気軽に申し込んだ。ところが、当日使う工具を持っていない場合は貸出料が必要で、材料費に加えて、壊れた部品を処分する費用もかかると後で知った。無料という言葉が間違っているわけではないが、最初から合計の目安が分かれば、参加するかどうか判断しやすかったと思う。\n講座そのものは役に立った。講師は修理の方法を教えるばかりか、修理しないほうが安全な状態まで説明してくれた。私は何でも直せることが良い技術だと思っていたが、電気が通る部分に傷がある場合など、家庭で作業を続けないほうがよい理由を学んだ。工具を借りるだけなら料金は高く感じるが、判断の仕方を学べる点には価値があった。\n終了後、参加者の一人が「費用の説明が遅かった」と意見を伝えた。工房は次回から、持参できる物、借りる物、必要な材料、追加費用が発生する条件を申込前に示すことにした。ただし、故障の状態によって部品が違うため、最終金額を完全に固定するのは難しい。そのため、費用の幅と、作業を始める前に確認する手順を併記するそうだ。安さを知らせることと、安心して選べる情報を出すことは別の仕事である。魅力を伝える広告にも、判断に必要な条件を残してほしい。",
      "zh": "車站前的工坊開了免費修理課。廣告大寫參加費免費，我輕鬆就報名，後來才知道沒帶工具需付租借費，除了材料費，還有損壞零件的處理費。免費一詞不算錯，但若一開始知道總費用概估，就更容易決定是否參加。課程本身很實用。講師不只教修理，連哪些狀況不修更安全也有說明。我原本以為什麼都會修才是好技術，後來學到通電部分受損等情形不應在家繼續作業的理由。只看租工具會覺得貴，但學習如何判斷有價值。結束後，一位參加者反映費用說明太晚。工坊決定下次報名前就說明能自備與需租借的東西、所需材料及追加費用條件。不過故障狀況不同，所需零件也不同，很難完全固定最終金額，因此會同列費用區間與開始作業前的確認流程。宣傳便宜與提供能安心選擇的資訊，是兩件不同的工作；吸引人的廣告也應保留判斷所需條件。",
