      "sample": "修理講座の参加費は無料ですが、材料費に加えて、工具を借りる場合の貸出料が必要です。壊れた部品を処分する場合は、別の費用がかかることもあります。合計は故障の状態によって変わるため、申込時には費用の幅をお知らせし、作業を始める前に最終確認を行います。工具をお持ちの方は持参できますが、安全に使えるか講師が確認します。この講座では直し方を学ぶばかりか、修理を続けないほうがよい状態も学べます。費用と内容をご確認の上、ご自身の目的に合うか検討してからお申し込みください。",
