      "jp": "駅前の店が、雨の日に傘を貸すサービスを始めた。最初は十本だけだったが、利用者の増加に伴って、返却を確認する仕事も増えた。店主は傘の本数を増やせば便利になると思っていたものの、レジで返却日を調べる間に、普通の買い物客を待たせることが多くなった。サービスの規模が大きくなると、物を用意するだけでなく、管理の時間も変わるのである。\n店では、利用の目的に応じて貸出期間を変える案を検討した。駅までの短い移動なら当日中、旅行中なら三日以内に返してもらう。ただし目的を詳しく聞きすぎると、手続きに時間がかかり、利用者も話しにくい。そこで二種類の期間を掲示し、利用者に選んでもらう方法にした。遠方から来た人には、別の協力店でも返却できることを説明する。\n返却された傘は、すぐ次の人に貸せるとは限らない。乾かし、骨が曲がっていないか確認する必要がある。店主は閉店前に一人で作業していたが、利用が増えた後は毎日続けるのが難しくなった。近くの店と相談し、曜日ごとに点検を分担することになった。便利なサービスを増やす時には、使う人の条件に合わせる工夫と、支える側の仕事量の見直しを同時に考えたい。本数だけを数えて成果とすると、見えない負担に気づくのが遅れてしまう。",
