      "jp": "町の避難地図には、川沿いの細い道が近道として載っていた。しかし大雨の時には、その道が通れなくなるおそれがある。新しい地図を作る担当者は、普段歩ける道をそのまま避難経路にすると、危険な場所へ人を誘導しかねないと考えた。地図の線が分かりやすいことだけでは、安全な判断を助けるとは限らない。\n担当者は、昼の晴れた日に歩いた記録と、雨の日に水がたまった場所の写真を比較した。橋の下は晴れた日なら便利だが、短時間で水が増える場所だった。一方、坂の上の道は水の影響が少ないものの、車いすでは通りにくい。すべての人に同じ一本の経路を示すことは難しい。そこで、雨で避ける道と、移動に支援が必要な道を別の記号で表した。\n住民の説明会では、記号が多すぎて分かりにくいという意見も出た。担当者は重要な注意を二つに絞り、詳しい条件は地図の裏面へ移した。ただし裏面を見なければ危険が分からない作りにはせず、表にも短い警告を残した。地図は状況をリアルタイムで知らせるものではないため、実際の避難時には最新の案内を確認する必要がある。正確な資料でも、古い情報を確実な事実として読めば、判断を誤る可能性がある。地図には作成日と連絡先も記載し、次の点検の時期を決めることにした。",
