      "sample": "相談室の開設に際して、利用説明会を行います。開設に先立って、初めて使う保護者の方にも操作を試していただきました。その結果、相談内容の項目が分かりにくいことと、画面を戻ると文章が消えることが分かりました。項目の説明を加え、一時保存も用意します。ただし、共用端末に個人の内容が残らないよう、保存には有効期間を設けます。説明会では、相談できる範囲と回答までの時間もお知らせします。緊急の場合は通常の予約を待たず、案内の別の連絡先をご確認ください。開設後もご意見を聞いて改善します。",
