      "jp": "地域の活動を支援する助成金に、私たちの団体も応募した。結果が分かり次第、代表が全員に連絡すると約束した。しかし審査が長引き、予定していた会場の予約期限が近づいた。まだ決まっていないのに支援を受けられるつもりで契約すると、採用されなかった場合に費用を払えなくなる。代表は毎日結果を確認したが、問い合わせても確実な日付は分からなかった。\n団体は、資金が出るまで待つ案と、規模を小さくして自費で始める案を何度も話し合った。前者なら広い会場を使えるが、開催日を決められない。後者なら日付を守れるが、参加できる人数が少なくなる。検討を重ねた末に、最初は十人の小さな会を開き、助成が決まった後で追加の回を設けることにした。申込者には、参加できる回数がまだ未定であることも説明した。\nその翌週、採用の通知が届いた。代表はすぐに連絡したが、最初の契約を大きな会場へ変えることはしなかった。既に小さな会の準備を進めており、急に変更すれば協力者の予定や説明をやり直す必要があるからだ。資金があることと、すぐに規模を広げることは同じではない。知らせる速さと、決める前の慎重さは両立できる。結果が届いたらすぐ共有し、その結果をどう使うかは、これまでの合意と現場の条件を確かめてから判断することが大切だ。",
      "zh": "我們團體申請地方活動補助，代表承諾一知結果立即聯絡全員，但審查拖長，場地預訂期限將近。若在尚未確定前先當作會獲補助簽約，落選時可能付不出費用。代表每天查，詢問也無法得知確定日期。團體反覆討論等資金與縮規模自費兩案：前者可用大場但日子未定，後者能守日期但人數少。最後決定先辦十人小聚，獲助後再加場，並告訴報名者場次還未定。下一週獲錄取通知，代表立刻告知，卻沒把首場換成大場，因為小聚已在準備，驟改需重排協作者計畫及說明。有資金不等於應立刻擴大。通知快與決策慎重可以並存，結果應立即共享，如何使用仍要確認既有共識與現場條件再判斷。",
