      "jp": "博物館は、休日の混雑を減らすため、平日の入館料を下げた。担当者は休日の客が平日へ移ると予想し、三か月にわたって来場者を調べた。ところが予想に反して、休日の人数はあまり減らず、平日だけが増えた。最初の報告では、値下げによって全体の利用が広がったと評価されたが、数字の中身を確かめる必要があった。\n時間帯と団体の種類を分けて見ると、平日の午前に学校の見学が増えていた。個人の客が休日から移ったのではなく、新しく団体が来るようになったのである。学校は値段だけでなく、説明を担当する職員のいる時間を選んでいた。値下げと見学の増加は同時に起きたが、料金だけが理由だと決めることはできない。職員が足りない日には、低い料金でも希望に応じられなかった。\n博物館は、団体を受け入れる日と時間を案内し、予約の段階で必要な支援を確認することにした。一方で、静かに展示を見たい個人の客には、団体の少ない時間を知らせる。ただし、学校の予定は急に変わることがあるので、毎日同じ状態を保証することはできない。三か月の調査は、一日の数字より多くのことを示したが、年間の傾向を完全に表すものでもない。予想と違う結果を失敗として隠すのではなく、誰の利用がどう増えたのかを説明すれば、次の運営を考える根拠になる。",
